-- =====================================================================
-- Gold: SILVER.SLV_ITEM -> RETAIL_DW.DIM_ITEM
-- SCD2 on BRAND_NM and SUBCATG_KY (history kept):
--   1. close the current version when brand or subcategory changed
--      (EFF_END_DT = day before, CURR_FLG = FALSE)
--   2. insert a new current version for changed and brand-new items;
--      ITEM_KY is generated by AUTOINCREMENT (the surrogate key)
-- SCD1 on ITEM_NM (overwritten in place on every version).
-- Rerun safety:
--   * a version is only closed if this date is after its start date,
--     so rerunning the same or an older date closes nothing;
--   * a new version is only inserted when the item has no current row;
--   * the SCD1 overwrite only runs for the latest loaded date.
-- =====================================================================
CREATE OR REPLACE TEMPORARY TABLE SILVER.TMP_ITEM_SRC AS
SELECT s.ITEM_ID, s.ITEM_NAME, s.BRAND_NAME, sc.SUBCATG_KY
FROM SILVER.SLV_ITEM s
JOIN RETAIL_DW.DIM_SUBCATG sc ON sc.SUBCATG_ID = s.SUBCLASS_ID
WHERE s.BUSINESS_DATE = TO_DATE('{{ ds }}')
QUALIFY ROW_NUMBER() OVER (PARTITION BY s.ITEM_ID ORDER BY s._LOAD_TS DESC) = 1;

BEGIN;

-- 1. SCD2: close current versions whose tracked attributes changed
UPDATE RETAIL_DW.DIM_ITEM t
   SET EFF_END_DT = DATEADD(day, -1, TO_DATE('{{ ds }}')),
       CURR_FLG   = FALSE,
       UPDATE_TS  = CURRENT_TIMESTAMP()
  FROM SILVER.TMP_ITEM_SRC s
 WHERE t.ITEM_ID = s.ITEM_ID
   AND t.CURR_FLG
   AND TO_DATE('{{ ds }}') > t.EFF_START_DT
   AND (t.SUBCATG_KY <> s.SUBCATG_KY
        OR UPPER(COALESCE(t.BRAND_NM, '')) <> UPPER(COALESCE(s.BRAND_NAME, '')));

-- 2. SCD2: new current version for changed or new items
INSERT INTO RETAIL_DW.DIM_ITEM (ITEM_ID, ITEM_NM, BRAND_NM, SUBCATG_KY, CURR_FLG, EFF_START_DT, EFF_END_DT)
SELECT s.ITEM_ID, s.ITEM_NAME, s.BRAND_NAME, s.SUBCATG_KY, TRUE,
       TO_DATE('{{ ds }}'), DATE '9999-12-31'
FROM SILVER.TMP_ITEM_SRC s
WHERE NOT EXISTS (SELECT 1 FROM RETAIL_DW.DIM_ITEM t
                  WHERE t.ITEM_ID = s.ITEM_ID AND t.CURR_FLG);

-- 3. SCD1: item name corrected in place (latest loaded date only)
UPDATE RETAIL_DW.DIM_ITEM t
   SET ITEM_NM = s.ITEM_NAME, UPDATE_TS = CURRENT_TIMESTAMP()
  FROM SILVER.TMP_ITEM_SRC s
 WHERE t.ITEM_ID = s.ITEM_ID
   AND t.ITEM_NM <> s.ITEM_NAME
   AND TO_DATE('{{ ds }}') >= (SELECT COALESCE(MAX(BUSINESS_DATE), TO_DATE('1900-01-01'))
                               FROM SILVER.AUD_RECONCILIATION);

COMMIT;

-- ROWS_OK = current versions; ROWS_REJECTED = items whose subclass is not in DIM_SUBCATG
SELECT
    (SELECT COUNT(*) FROM RETAIL_DW.DIM_ITEM WHERE CURR_FLG) AS ROWS_OK,
    (SELECT COUNT(*) FROM SILVER.SLV_ITEM WHERE BUSINESS_DATE = TO_DATE('{{ ds }}'))
      - (SELECT COUNT(*) FROM SILVER.TMP_ITEM_SRC)          AS ROWS_REJECTED;
